import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0038: Local presentation gate and professional interface","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0038-professional-presentation-gate.md","filePath":"adrs/0038-professional-presentation-gate.md","lastUpdated":1789092097000}`),u={name:`adrs/0038-professional-presentation-gate.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[11]||=a(`<h1 id="adr-0038-local-presentation-gate-and-professional-interface" tabindex="-1">ADR-0038: Local presentation gate and professional interface <a class="header-anchor" href="#adr-0038-local-presentation-gate-and-professional-interface" aria-label="Permalink to “ADR-0038: Local presentation gate and professional interface”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-05 · Refines <a href="/adrs/0030-corporate-default-and-unlockable-1337-experience">0030</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The user approved the professional interface pass and supplied light/dark figurehead assets. Existing mascot views, menus, reaction effects, and icons did not yet share an unlock gate. The user explicitly requested typing <code>1337</code> in About, simplifying ADR-0030&#39;s arming chord.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>PresentationPreferences</code> owns a persistent, local unlock and a separately switchable active presentation. It fails closed: an enabled preference without an unlock does nothing. Only About recognizes the four digits, within ten seconds, while its window is key and the app is active. Losing window focus, invalid input, or timeout resets capture. Pasted strings and key repeat cannot complete it. There is no global keyboard hook or storage of typed input.</p><p>Unlocking is idempotent, activates the pack, and selects the hidden built-in theme. A progress ring and brief confirmation acknowledge it. System appearance or the unlocked presentation switch restores professional presentation while retaining the unlock. No model, prompt, memory, rating, permission, or tool behavior depends on this preference.</p>`,7),c(`p`,null,[l[1]||=i(`All mascot renderers have a professional light/dark figurehead fallback. `,-1),r(m,{term:`effort`},{default:n(()=>[...l[0]||=[i(`Effort`,-1)]]),_:1}),l[2]||=i(` icons, reaction effects, thinking bubbles, playful copy, and alternate icons are gated. About cycles poses in order only with the presentation active. Motion additionally respects the animation preference, Reduce Motion, and scene activity. The professional thinking label has a bounded 30 Hz theme-gradient sweep, with a static fallback.`,-1)]),l[12]||=c(`p`,null,`The main window, Settings, About, and shared dialogs apply the same tint and accent environment. AppKit editors receive themed carets and selection colors. System follows light/dark changes; professional icons follow the resolved appearance unless the user selects Light or Dark. The canonical packaged icon uses the existing professional Light artwork.`,-1),l[13]||=c(`h2`,{id:`consequences`,tabindex:`-1`},[i(`Consequences `),c(`a`,{class:`header-anchor`,href:`#consequences`,"aria-label":`Permalink to “Consequences”`},`​`)],-1),c(`p`,null,[l[4]||=i(`Public user documentation and landing-page copy use the professional identity and do not advertise the unlock. Historical ADRs retain implementation decisions for maintainers. The presentation flag is a preference, not an authorization or security boundary. Built-in light-theme accents are darkened for contrast; community `,-1),r(m,{term:`theme`},{default:n(()=>[...l[3]||=[i(`themes`,-1)]]),_:1}),l[5]||=i(` remain user data. Window translucency and the known fullscreen compositor limitation are unchanged.`,-1)]),l[14]||=c(`h2`,{id:`alternatives-considered`,tabindex:`-1`},[i(`Alternatives considered `),c(`a`,{class:`header-anchor`,href:`#alternatives-considered`,"aria-label":`Permalink to “Alternatives considered”`},`​`)],-1),c(`p`,null,[l[8]||=i(`Independent flags in each view risk missed surfaces and inconsistent startup behavior. Gating actual `,-1),r(m,{term:`goated`},{default:n(()=>[...l[6]||=[i(`extension`,-1)]]),_:1}),l[9]||=i(),r(m,{term:`tool`},{default:n(()=>[...l[7]||=[i(`tools`,-1)]]),_:1}),l[10]||=i(` would alter functionality, so only their display branding changes. Remote flags and global keyboard monitors are unnecessary for a local presentation preference.`,-1)])])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};